    home_premium_badge_label: "Premium", premium_unlock_title: "Premium Unlocked!", premium_unlock_desc: "Custom themes, the AI planner, the goal of the month and 50 AI photo scans a month are all yours now.", premium_unlock_cta: "Let's go!",
