    habits_title: "Hábitos", habits_empty_hint: "Ainda não há hábitos - adicione um para começar a acompanhar sua sequência.", habits_add_modal_title: "Novo hábito", habits_name_placeholder: "ex. Beber água, Ler, Meditar...", habits_missing_name: "Por favor, dê um nome ao hábito", habits_delete_title: "Excluir este hábito?", habits_delete_confirm: "Isso também excluirá permanentemente todo o seu histórico e sequência.", habits_link_sport_label: "Também registrar isso como sessão de esporte ao concluir", habits_sport_duration_placeholder: "Duração em minutos", habits_missing_sport_duration: "Digite a duração em minutos", habit_auto_logged_sport_badge: "De um hábito", habits_overview_btn_title: "Visão geral mensal", habits_overview_title: "Hábitos - Visão geral mensal", routine_goals_section_title: "🎯 Metas e Hábitos", routine_goals_empty_hint: "Ainda não há nada nesta aba - adicione itens à sua rotina para acompanhá-los aqui.", routine_goals_toggle_label: "Mostrar acompanhamento de metas e hábitos",
    habit_history_btn_title: "Ver histórico", habit_streak_at_risk_title: "Ontem foi perdido - marque hoje ou a sequência termina", habit_history_stat_current: "🔥 Atual", habit_history_stat_best: "🏆 Melhor", habit_history_stat_total: "✅ Total",
