    vision_routine_added_toast: "已添加到我的日常 ✓",
    vision_routine_add_btn: "添加到日常",
    vision_routine_no_free_hours: "这个标签页没有空闲时间 – 请在「我的日常」（⚙️）中添加时间。",
    vision_routine_hour_taken: "已占用",
    vision_routine_hour_label: "时间",
    vision_routine_tab_label: "标签页",
