    calorie_stat_avg_label: "Wastani: {amount}",
    daily_focus_modal_title: "🧠 Ni jambo gani muhimu zaidi unalotaka kufanya leo?", daily_focus_modal_subtitle: "Jibu, nalo litaongezwa moja kwa moja kwenye ratiba ya leo.", daily_focus_input_placeholder: "Leo ninachotaka zaidi ni", daily_focus_save_btn: "Ongeza kwenye ratiba ya leo", daily_focus_skip_btn: "Si sasa", daily_focus_missing_text: "Andika kitu kwanza", daily_focus_added_toast: "Imeongezwa kwenye ratiba ya leo", daily_focus_other_option: "✍️ Nyingine...",
    daily_focus_c1_d0: "Kulinda nafasi yangu ya utulivu dhidi ya kelele zinazonizunguka", daily_focus_c1_d1: "Kuweka mipaka wazi, kwa upendo na bila hatia", daily_focus_c1_d2: "Kubaki imara hata pale dhoruba inapozunguka", daily_focus_c1_d3: "Kuweka utulivu na nguvu zangu kuwa kipaumbele cha kwanza", daily_focus_c1_d4: "Kutobeba hisia na hali za moyo za wengine", daily_focus_c1_d5: "Kutoruhusu maneno ya wengine kutikisa thamani yangu",
    daily_focus_c2_d0: "Kusikiliza kile ambacho mwili na akili yangu vinahitaji", daily_focus_c2_d1: "Kufurahia mambo madogo njiani", daily_focus_c2_d2: "Kupunguza kasi na kuungana kikweli na nafsi yangu", daily_focus_c2_d3: "Kujipatia nafasi ya kupumzika katikati ya shughuli", daily_focus_c2_d4: "Kujisikia nyumbani na kwa amani ndani yangu", daily_focus_c2_d5: "Kuzingatia kinachotokea sasa, bila kukimbilia mbele",
    daily_focus_c3_d0: "Kuweka maneno yangu ya kutia moyo, ya subira na ya kuelewa", daily_focus_c3_d1: "Kutochukua kitu chochote kibinafsi", daily_focus_c3_d2: "Kutodhania - badala yake kuuliza, au kuachilia", daily_focus_c3_d3: "Kuamini mwendo wangu mwenyewe na njia yangu", daily_focus_c3_d4: "Kuachilia ukamilifu na kuchagua maendeleo", daily_focus_c3_d5: "Kuwa na subira na mchakato wangu mwenyewe",
    daily_focus_c4_d0: "Kumaliza siku nikiwa na hisia ya fahari na kuridhika", daily_focus_c4_d1: "Kutambua maendeleo yangu, hata kwa hatua ndogo", daily_focus_c4_d2: "Kuzingatia kazi moja kwa wakati mmoja", daily_focus_c4_d3: "Kupanga mambo yangu vizuri na kutenda kwa utulivu", daily_focus_c4_d4: "Kujikubali jinsi nilivyo leo", daily_focus_c4_d5: "Kujua wakati wa kutenda na wakati wa kuachilia",
    daily_focus_c5_d0: "Kuleta tabasamu na wepesi katika kila ninachofanya", daily_focus_c5_d1: "Kuanza siku na nguvu mpya, njema", daily_focus_c5_d2: "Kujipatia siku moja tulivu, bila matarajio makubwa kupita kiasi", daily_focus_c5_d3: "Kuleta furaha rahisi katika utaratibu wangu wa kila siku", daily_focus_c5_d4: "Kufungua moyo wangu kwa mshangao mzuri leo", daily_focus_c5_d5: "Kuanza siku kwa shukrani na tabasamu",
