    auth_forgot_password_link: "Umesahau nenosiri?", auth_back_to_login: "Rudi kwenye kuingia", auth_forgot_subtitle: "Weka barua pepe yako na tutakutumia kiungo cha kuweka upya:", auth_forgot_submit_btn: "Tuma kiungo cha kuweka upya", auth_fill_email: "Tafadhali weka barua pepe yako", auth_forgot_success: "Ikiwa barua pepe hiyo ipo, kiungo cha kuweka upya kinatumwa - angalia kikasha chako.",
