    tables_menu_label: "Tábìlì", tables_title: "Àwọn Tábìlì", tables_empty_hint: "Kò sí tábìlì síbẹ̀ - ṣẹ̀dá ọ̀kan láti bẹ̀rẹ̀.", table_add_modal_title: "Tábìlì Tuntun", table_edit_modal_title: "Ṣàtúnṣe Tábìlì", table_name_placeholder: "Orúkọ tábìlì...", table_icon_label: "Àmì", table_manage_columns_btn: "Àwọn Kọ́lọ́mù", table_add_row_btn: "+ Fi ìlà kún", table_delete_title: "Pa tábìlì yìí rẹ́?", table_delete_confirm: "Èyí yóò pa tábìlì náà, gbogbo àwọn kọ́lọ́mù rẹ̀ àti gbogbo àwọn ìlà rẹ̀ rẹ́ pátápátá. A kò lè fagilé èyí.", table_no_columns_hint: "Kò sí kọ́lọ́mù síbẹ̀ - tẹ \"Àwọn Kọ́lọ́mù\" láti fi èyí àkọ́kọ́ kún.", table_no_rows_hint: "Kò sí ìlà síbẹ̀ - tẹ \"+ Fi ìlà kún\" láti bẹ̀rẹ̀.", table_manage_columns_title: "Àwọn Kọ́lọ́mù", table_add_column_btn: "+ Fi kọ́lọ́mù kún", table_add_column_modal_title: "Kọ́lọ́mù Tuntun", table_column_name_placeholder: "Orúkọ kọ́lọ́mù...", table_column_type_label: "Irú", table_column_type_text: "Ọ̀rọ̀", table_column_type_number: "Nọ́mbà", table_column_type_checkbox: "Àmì Àyẹ̀wò", table_column_type_select: "Yíyàn", table_column_type_date: "Ọjọ́", table_column_delete_title: "Pa kọ́lọ́mù yìí rẹ́?", table_column_delete_confirm: "Èyí yóò pa kọ́lọ́mù náà àti data rẹ̀ nínú gbogbo ìlà rẹ́ pátápátá. A kò lè fagilé èyí.", table_column_options_label: "Àwọn Àṣàyàn", table_add_option_btn: "+ Fi àṣàyàn kún", table_column_option_placeholder: "Orúkọ àṣàyàn...", table_column_needs_option_error: "Fi o kéré tán àṣàyàn kan kún ná.", table_select_cell_picker_title: "Yan iye kan", table_select_cell_clear: "Nu", table_save_btn: "Fi pamọ́", ai_brain_tab_table: "🗂️ Tábìlì", table_ai_modal_subtitle: "Ṣàpèjúwe tábìlì tí o fẹ́ (f.a. \"ìṣètò àwọn ẹ̀bùn àjọ̀dún - fún ta, èrò, ìṣúnná, ǹjẹ́ a ti rà á?\") kí o sì jẹ́ kí AI ṣe àpẹrẹ àwọn kọ́lọ́mù fún ọ - ìwọ yóò fi àwọn ìlà kún fúnra rẹ nígbà tí ó bá yá.", table_ai_placeholder: "f.a. Ìṣètò àwọn ẹ̀bùn àjọ̀dún - fún ta, èrò, ìṣúnná, ǹjẹ́ a ti rà á?", table_ai_build_btn: "Ṣẹ̀dá Tábìlì", table_ai_loading_text: "Ń ṣẹ̀dá tábìlì rẹ...", ai_table_builder_entry_tooltip: "Ṣẹ̀dá tábìlì pẹ̀lú AI", ai_table_builder_empty: "Ṣàpèjúwe tábìlì tí o fẹ́ kọ́kọ́", ai_table_builder_ready: "Tábìlì rẹ tí AI ṣẹ̀dá ti ṣetán! Tẹ \"Fi Kún\" nísàlẹ̀, lẹ́yìn náà tẹ \"Fi pamọ́\" ní ojú-ìwé tí ó tẹ̀lé, kí ó lè jẹ́ ṣíṣẹ̀dá ní tòótọ́.", table_ai_review_title: "🧠 Tábìlì AI ti ṣetán - tẹ \"Fi Kún\" láti ṣẹ̀dá rẹ̀", table_ai_review_columns_hint: "🧠 Tábìlì tí AI ṣẹ̀dá - tẹ \"Fi pamọ́\" nísàlẹ̀ nígbà tí inú rẹ bá dùn sí àwọn kọ́lọ́mù wọ̀nyí, bí bẹ́ẹ̀ kọ́ a kì yóò ṣẹ̀dá tábìlì rẹ.", ai_table_builder_failed: "A kò lè ṣẹ̀dá tábìlì náà báyìí - jọ̀wọ́ gbìyànjú lẹ́ẹ̀kan síi",
