    habits_empty_hint: "Ingen vaner ennå - legg til en for å begynne å spore streken din.", habits_add_modal_title: "Ny vane", habits_name_placeholder: "f.eks. Drikk vann, Les, Meditere...", habits_missing_name: "Gi vanen et navn", habits_delete_title: "Slette denne vanen?", habits_delete_confirm: "Dette sletter også permanent all historikken og streken dens.", habits_link_sport_label: "Logg dette også som en treningsøkt når det fullføres", habits_sport_duration_placeholder: "Varighet i minutter", habits_missing_sport_duration: "Angi varigheten i minutter", habit_auto_logged_sport_badge: "Fra en vane", habits_overview_btn_title: "Månedsoversikt", habits_overview_title: "Vaner - Månedsoversikt", routine_goals_section_title: "🎯 Mål & Vaner", routine_goals_empty_hint: "Ingenting i denne fanen ennå - legg til punkter i rutinen din for å følge dem her.", routine_goals_toggle_label: "Vis sporing av mål & vaner",
    schedule_move_slot_title: "Flytt til en annen dag", schedule_move_slot_confirm_btn: "Flytt", schedule_move_slot_empty: "Legg til en tittel på denne oppgaven før du flytter den", schedule_move_slot_success: "Oppgave flyttet ✅",
