    habits_empty_hint: "Ingen vaner endnu - tilføj en for at begynde at spore din stribe.", habits_add_modal_title: "Ny vane", habits_name_placeholder: "f.eks. Drik vand, Læs, Meditér...", habits_missing_name: "Giv venligst vanen et navn", habits_delete_title: "Slet denne vane?", habits_delete_confirm: "Dette vil også permanent slette al dens historik og stribe.", habits_link_sport_label: "Log også dette som en træningssession, når det er fuldført", habits_sport_duration_placeholder: "Varighed i minutter", habits_missing_sport_duration: "Angiv varigheden i minutter", habit_auto_logged_sport_badge: "Fra en vane", habits_overview_btn_title: "Månedsoversigt", habits_overview_title: "Vaner - Månedsoversigt", routine_goals_section_title: "🎯 Mål & Vaner", routine_goals_empty_hint: "Intet i denne fane endnu - tilføj punkter til din rutine for at følge dem her.", routine_goals_toggle_label: "Vis sporing af mål & vaner",
    schedule_move_slot_title: "Flyt til en anden dag", schedule_move_slot_confirm_btn: "Flyt", schedule_move_slot_empty: "Tilføj en titel til denne opgave, før du flytter den", schedule_move_slot_success: "Opgave flyttet ✅",
